namespace sarif.export.relocs;





using ghidra.program.model.reloc;
using ghidra.util.exception;
using ghidra.util.task;
using sarif.export;
using sarif.export;
using sarif.managers;

public class SarifRelocationWriter : AbstractExtWriter {

	List<Relocation> relocs;

	public SarifRelocationWriter(List<Relocation> request, Writer baseWriter)
    : base(baseWriter)
    {
		this.relocs = request;
	}

	/* @Override */
	protected void genRoot(TaskMonitor monitor)
    {
		genRelocation(monitor);
		root.add("relocations", objects);
	}

	private void genRelocation(TaskMonitor monitor)
    {
		monitor.initialize(relocs.size());
		foreach (Relocation r in relocs) {
			monitor.checkCancelled();
			ExtRelocation isf = new ExtRelocation(r);
			SarifObject sarif = new SarifObject(RelocationTableSarifMgr.SUBKEY, RelocationTableSarifMgr.KEY,
					getTree(isf), r.getAddress(), r.getAddress());
			objects.add(getTree(sarif));
			monitor.increment();
		}
	}

}
